31 14:53:12','2026-10-31 14:53:12'),(13,3,'Silly Bandz (Pack of 24)','silly-bandz-pack-of-24','Shaped rubber bands you wore, traded and collected.',75000.00,100,NULL,1,'2026-10-31 14:53:12','2026-10-31 14:53:12'),(14,3,'Beyblade Metal Fusion Starter','beyblade-metal-fusion-starter','Rip the launcher and let it rip!',180000.00,40,NULL,1,'2026-10-31 14:53:12','2026-10-31 14:53:12'),(15,3,'Furby (2012)','furby-2012','The wide-eyed talking companion, now with an app.',650000.00,12,NULL,1,'2026-10-31 14:53:12','2026-10-31 14:53:12'),(16,3,'Nerf Maverick REV-6','nerf-maverick-rev-6','Six-dart revolver for the ultimate indoor skirmish.',250000.00,22,NULL,1,'2026-10-31 14:53:12','2026-10-31 14:53:12'),(17,4,'Avatar (2009) DVD','avatar-2009-dvd','Return to Pandora in the film that redefined the box office.',120000.00,50,NULL,1,'2026-10-31 14:53:12','2026-10-31 14:53:12'),(18,4,'The Dark Knight Blu-ray','the-dark-knight-blu-ray','Why so serious? Nolan\'s definitive Batman in HD.',180000.00,35,NULL,1,'2026-10-31 14:53:12','2026-10-31 14:53:12'),(19,4,'Linkin Park - Meteora (CD)','linkin-park-meteora-cd','Nu-metal anthems that ruled every MP3 player.',150000.00,28,NULL,1,'2026-10-31 14:53:12','2026-10-31 14:53:12'),(20,4,'Shrek Forever After DVD','shrek-forever-after-dvd','The final chapter of everyone\'s favourite ogre.',110000.00,18,NULL,1,'2026-10-31 14:53:12','2026-10-31 14:53:12');
